    43→	// ByRangeRequestDataColumnSidecarRequirements defines the set of requirements that DataColumnSidecars received
    44→	// via the by range request must satisfy in order to upgrade an RODataColumn to a VerifiedRODataColumn.
    45→	// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#datacolumnsidecarsbyrange-v1
    46→	ByRangeRequestDataColumnSidecarRequirements = []Requirement{
