    48→		RequireSidecarInclusionProven,
    49→		RequireSidecarKzgProofVerified,
    50→	}
    51→
    52→	// ByRootRequestDataColumnSidecarRequirements defines the set of requirements that DataColumnSidecars received
    53→	// via the by root request must satisfy in order to upgrade an RODataColumn to a VerifiedRODataColumn.
    54→	// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#datacolumnsidecarsbyroot-v1
    55→	ByRootRequestDataColumnSidecarRequirements = []Requirement{
