    61→	// SpectestDataColumnSidecarRequirements is used by the forkchoice spectests when verifying data columns used in the on_block tests.
    62→	SpectestDataColumnSidecarRequirements = requirementList(GossipDataColumnSidecarRequirements).excluding(
    63→		RequireSidecarParentSeen, RequireSidecarParentValid)
    64→
    65→	errColumnsInvalid = errors.New("data columns failed verification")
    66→	errBadTopicLength = errors.New("topic length is invalid")
