    70→type LazyHeadStateProvider struct {
    71→	HeadStateProvider
    72→}
    73→
    74→var _ HeadStateProvider = &LazyHeadStateProvider{}
    75→
    76→type (
    77→	RODataColumnsVerifier struct {
    78→		*sharedResources
    79→		results                     *results
    80→		dataColumns                 []blocks.RODataColumn
    81→		verifyDataColumnsCommitment rodataColumnsCommitmentVerifier
    82→		stateByRoot                 map[[fieldparams.RootLength]byte]state.BeaconState
    83→	}
    84→
    85→	rodataColumnsCommitmentVerifier func([]blocks.RODataColumn) error
    86→)
    87→
    88→var _ DataColumnsVerifier = &RODataColumnsVerifier{}
    89→
    90→// VerifiedRODataColumns "upgrades" wrapped RODataColumns to VerifiedRODataColumns.
    91→// If any of the verifications ran against the data columns failed, or some required verifications
    92→// were not run, an error will be returned.
    93→func (dv *RODataColumnsVerifier) VerifiedRODataColumns() ([]blocks.VerifiedRODataColumn, error) {
    94→	if !dv.results.allSatisfied() {
    95→		return nil, dv.results.errors(errColumnsInvalid)
    96→	}
    97→
    98→	verifiedRODataColumns := make([]blocks.VerifiedRODataColumn, 0, len(dv.dataColumns))
    99→	for _, dataColumn := range dv.dataColumns {
   100→		verifiedRODataColumn := blocks.NewVerifiedRODataColumn(dataColumn)
   101→		verifiedRODataColumns = append(verifiedRODataColumns, verifiedRODataColumn)
   102→	}
   103→
   104→	return verifiedRODataColumns, nil
   105→}
   106→
   107→// SatisfyRequirement allows the caller to assert that a requirement has been satisfied.
   108→// This gives us a way to tick the box for a requirement where the usual method would be impractical.
   109→// For example, when batch syncing, forkchoice is only updated at the end of the batch. So the checks that use
   110→// forkchoice, like descends from finalized or parent seen, would necessarily fail. Allowing the caller to
   111→// assert the requirement has been satisfied ensures we have an easy way to audit which piece of code is satisfying
   112→// a requirement outside of this package.
   113→func (dv *RODataColumnsVerifier) SatisfyRequirement(req Requirement) {
   114→	dv.recordResult(req, nil)
   115→}
   116→
   117→func (dv *RODataColumnsVerifier) recordResult(req Requirement, err *error) {
   118→	if err == nil || *err == nil {
   119→		dv.results.record(req, nil)
   120→		return
   121→	}
   122→	dv.results.record(req, *err)
   123→}
   124→
   125→func (dv *RODataColumnsVerifier) ValidFields() (err error) {
   126→	if ok, err := dv.results.cached(RequireValidFields); ok {
   127→		return err
   128→	}
   129→
   130→	defer dv.recordResult(RequireValidFields, &err)
   131→
   132→	for _, dataColumn := range dv.dataColumns {
   133→		if err := peerdas.VerifyDataColumnSidecar(dataColumn); err != nil {
   134→			return columnErrBuilder(errors.Wrap(err, "verify data column sidecar"))
   135→		}
   136→	}
   137→
   138→	return nil
   139→}
   140→
   141→func (dv *RODataColumnsVerifier) CorrectSubnet(dataColumnSidecarSubTopic string, expectedTopics []string) (err error) {
   142→	if ok, err := dv.results.cached(RequireCorrectSubnet); ok {
   143→		return err
   144→	}
   145→
   146→	defer dv.recordResult(RequireCorrectSubnet, &err)
   147→
   148→	if len(expectedTopics) != len(dv.dataColumns) {
   149→		return columnErrBuilder(errBadTopicLength)
   150→	}
   151→
   152→	for i := range dv.dataColumns {
   153→		// We add a trailing slash to avoid, for example,
   154→		// an actual topic /eth2/9dc47cc6/data_column_sidecar_1
   155→		// to match with /eth2/9dc47cc6/data_column_sidecar_120
   156→		expectedTopic := expectedTopics[i] + "/"
   157→
   158→		actualSubnet := peerdas.ComputeSubnetForDataColumnSidecar(dv.dataColumns[i].Index)
   159→		actualSubTopic := fmt.Sprintf(dataColumnSidecarSubTopic, actualSubnet)
   160→
   161→		if !strings.Contains(expectedTopic, actualSubTopic) {
   162→			return columnErrBuilder(errBadTopic)
   163→		}
   164→	}
   165→
   166→	return nil
   167→}
   168→
   169→func (dv *RODataColumnsVerifier) NotFromFutureSlot() (err error) {
   170→	if ok, err := dv.results.cached(RequireNotFromFutureSlot); ok {
   171→		return err
   172→	}
   173→
   174→	defer dv.recordResult(RequireNotFromFutureSlot, &err)
   175→
   176→	// Retrieve the current slot.
   177→	currentSlot := dv.clock.CurrentSlot()
   178→
   179→	// Get the current time.
   180→	now := dv.clock.Now()
   181→
   182→	// Retrieve the maximum gossip clock disparity.
   183→	maximumGossipClockDisparity := params.BeaconConfig().MaximumGossipClockDisparityDuration()
   184→
   185→	for _, dataColumn := range dv.dataColumns {
   186→		// Extract the data column slot.
   187→		dataColumnSlot := dataColumn.Slot()
   188→
   189→		// Skip if the data column slot is the same as the current slot.
   190→		if currentSlot == dataColumnSlot {
   191→			continue
   192→		}
   193→
   194→		// earliestStart represents the time the slot starts, lowered by MAXIMUM_GOSSIP_CLOCK_DISPARITY.
   195→		// We lower the time by MAXIMUM_GOSSIP_CLOCK_DISPARITY in case system time is running slightly behind real time.
   196→		earliestStart, err := dv.clock.SlotStart(dataColumnSlot)
   197→		if err != nil {
   198→			return columnErrBuilder(errors.Wrap(err, "failed to determine slot start time from clock waiter"))
   199→		}
   200→		earliestStart = earliestStart.Add(-maximumGossipClockDisparity)
   201→
   202→		// If the system time is still before earliestStart, we consider the column from a future slot and return an error.
   203→		if now.Before(earliestStart) {
   204→			return columnErrBuilder(errFromFutureSlot)
   205→		}
   206→	}
   207→
   208→	return nil
   209→}
   210→
   211→func (dv *RODataColumnsVerifier) SlotAboveFinalized() (err error) {
   212→	if ok, err := dv.results.cached(RequireSlotAboveFinalized); ok {
   213→		return err
   214→	}
   215→
   216→	defer dv.recordResult(RequireSlotAboveFinalized, &err)
   217→
   218→	// Retrieve the finalized checkpoint.
   219→	finalizedCheckpoint := dv.fc.FinalizedCheckpoint()
   220→
   221→	// Compute the first slot of the finalized checkpoint epoch.
   222→	startSlot, err := slots.EpochStart(finalizedCheckpoint.Epoch)
   223→	if err != nil {
   224→		return columnErrBuilder(errors.Wrap(err, "epoch start"))
   225→	}
   226→
   227→	for _, dataColumn := range dv.dataColumns {
   228→		// Check if the data column slot is after first slot of the epoch corresponding to the finalized checkpoint.
   229→		if dataColumn.Slot() <= startSlot {
   230→			return columnErrBuilder(errSlotNotAfterFinalized)
   231→		}
   232→	}
   233→
   234→	return nil
   235→}
   236→
   237→func (dv *RODataColumnsVerifier) ValidProposerSignature(ctx context.Context) (err error) {
   238→	if ok, err := dv.results.cached(RequireValidProposerSignature); ok {
   239→		return err
   240→	}
   241→
   242→	defer dv.recordResult(RequireValidProposerSignature, &err)
   243→
   244→	for _, dataColumn := range dv.dataColumns {
   245→		// Extract the signature data from the data column.
   246→		signatureData := columnToSignatureData(dataColumn)
   247→
   248→		// Get logging fields.
   249→		fields := logging.DataColumnFields(dataColumn)
   250→		log := log.WithFields(fields)
   251→
   252→		// First check if there is a cached verification that can be reused.
   253→		seen, err := dv.sc.SignatureVerified(signatureData)
   254→		if err != nil {
   255→			log.WithError(err).Debug("Reusing failed proposer signature validation from cache")
   256→
   257→			columnVerificationProposerSignatureCache.WithLabelValues("hit-invalid").Inc()
   258→			return columnErrBuilder(ErrInvalidProposerSignature)
   259→		}
   260→
   261→		// If yes, we can skip the full verification.
   262→		if seen {
   263→			columnVerificationProposerSignatureCache.WithLabelValues("hit-valid").Inc()
   264→			continue
   265→		}
   266→
   267→		// Ensure the expensive signature verification is only performed once for
   268→		// concurrent requests for the same signature data.
   269→		if _, err, _ = dv.sg.Do(signatureData.concat(), func() (any, error) {
   270→			columnVerificationProposerSignatureCache.WithLabelValues("miss").Inc()
   271→
   272→			// Retrieve a state compatible with the data column for verification.
   273→			verifyingState, err := dv.getVerifyingState(ctx, dataColumn)
   274→			if err != nil {
   275→				return nil, columnErrBuilder(errors.Wrap(err, "verifying state"))
   276→			}
   277→
   278→			// Full verification, which will subsequently be cached for anything sharing the signature cache.
   279→			if err = dv.sc.VerifySignature(signatureData, verifyingState); err != nil {
   280→				return nil, columnErrBuilder(errors.Wrap(err, "verify signature"))
   281→			}
   282→
   283→			return nil, nil
   284→		}); err != nil {
   285→			return err
   286→		}
   287→	}
   288→
   289→	return nil
   290→}
   291→
   292→// getVerifyingState returns a state that is compatible with the column sidecar and can be used to verify signature and proposer index.
   293→// The returned state is guaranteed to be at the same epoch as the data column's epoch, and have the same randao mix and active
   294→// validator indices as the data column's parent state advanced to the data column's slot.
   295→func (dv *RODataColumnsVerifier) getVerifyingState(ctx context.Context, dataColumn blocks.RODataColumn) (state.ReadOnlyBeaconState, error) {
   296→	dataColumnSlot := dataColumn.Slot()
   297→	dataColumnEpoch := slots.ToEpoch(dataColumnSlot)
   298→	if dataColumnEpoch == 0 {
   299→		return dv.hsp.HeadStateReadOnly(ctx)
   300→	}
   301→	parentRoot := dataColumn.ParentRoot()
   302→	dcDependentRoot, err := dv.fc.DependentRootForEpoch(parentRoot, dataColumnEpoch-1)
   303→	if err != nil {
   304→		return nil, err
   305→	}
   306→	headRoot, err := dv.hsp.HeadRoot(ctx)
   307→	if err != nil {
   308→		return nil, err
   309→	}
   310→	headDependentRoot, err := dv.fc.DependentRootForEpoch(bytesutil.ToBytes32(headRoot), dataColumnEpoch-1)
   311→	if err != nil {
   312→		return nil, err
   313→	}
   314→	if dcDependentRoot == headDependentRoot {
   315→		headSlot := dv.hsp.HeadSlot()
   316→		headEpoch := slots.ToEpoch(headSlot)
   317→		if headEpoch == dataColumnEpoch || headEpoch == dataColumnEpoch-1 {
   318→			return dv.hsp.HeadStateReadOnly(ctx)
   319→		}
   320→		if headEpoch+1 < dataColumnEpoch {
   321→			headState, err := dv.hsp.HeadState(ctx)
   322→			if err != nil {
   323→				return nil, err
   324→			}
   325→			return transition.ProcessSlotsUsingNextSlotCache(ctx, headState, headRoot, dataColumnSlot)
   326→		}
   327→	}
   328→
   329→	logrus.WithFields(logrus.Fields{
   330→		"slot":       dataColumnSlot,
   331→		"parentRoot": fmt.Sprintf("%#x", parentRoot),
   332→		"headRoot":   fmt.Sprintf("%#x", headRoot),
   333→	}).Debug("Replying state for data column verification")
   334→	targetRoot, err := dv.fc.TargetRootForEpoch(parentRoot, dataColumnEpoch)
   335→	if err != nil {
   336→		return nil, err
   337→	}
   338→	targetState, err := dv.sr.StateByRoot(ctx, targetRoot)
   339→	if err != nil {
   340→		return nil, err
   341→	}
   342→	targetEpoch := slots.ToEpoch(targetState.Slot())
   343→	if targetEpoch == dataColumnEpoch || targetEpoch == dataColumnEpoch-1 {
   344→		return targetState, nil
   345→	}
   346→	return transition.ProcessSlotsUsingNextSlotCache(ctx, targetState, parentRoot[:], dataColumnSlot)
   347→}
   348→
   349→func (dv *RODataColumnsVerifier) SidecarParentSeen(parentSeen func([fieldparams.RootLength]byte) bool) (err error) {
   350→	if ok, err := dv.results.cached(RequireSidecarParentSeen); ok {
   351→		return err
   352→	}
   353→
   354→	defer dv.recordResult(RequireSidecarParentSeen, &err)
   355→
   356→	for _, dataColumn := range dv.dataColumns {
   357→		// Skip if the parent root has been seen.
   358→		parentRoot := dataColumn.ParentRoot()
   359→		if parentSeen != nil && parentSeen(parentRoot) {
   360→			continue
   361→		}
   362→
   363→		if !dv.fc.HasNode(parentRoot) {
   364→			return columnErrBuilder(errors.Wrapf(errSidecarParentNotSeen, "parent root: %#x", parentRoot))
   365→		}
   366→	}
   367→
   368→	return nil
   369→}
   370→
   371→func (dv *RODataColumnsVerifier) SidecarParentValid(badParent func([fieldparams.RootLength]byte) bool) (err error) {
   372→	if ok, err := dv.results.cached(RequireSidecarParentValid); ok {
   373→		return err
   374→	}
   375→
   376→	defer dv.recordResult(RequireSidecarParentValid, &err)
   377→
   378→	for _, dataColumn := range dv.dataColumns {
   379→		if badParent != nil && badParent(dataColumn.ParentRoot()) {
   380→			return columnErrBuilder(errSidecarParentInvalid)
   381→		}
   382→	}
   383→
   384→	return nil
   385→}
   386→
   387→func (dv *RODataColumnsVerifier) SidecarParentSlotLower() (err error) {
   388→	if ok, err := dv.results.cached(RequireSidecarParentSlotLower); ok {
   389→		return err
   390→	}
   391→
   392→	defer dv.recordResult(RequireSidecarParentSlotLower, &err)
   393→
   394→	for _, dataColumn := range dv.dataColumns {
   395→		// Compute the slot of the parent block.
   396→		parentSlot, err := dv.fc.Slot(dataColumn.ParentRoot())
   397→		if err != nil {
   398→			return columnErrBuilder(errors.Wrap(err, "slot"))
   399→		}
   400→
   401→		// Check if the data column slot is after the parent slot.
   402→		if parentSlot >= dataColumn.Slot() {
   403→			return columnErrBuilder(errSlotNotAfterParent)
   404→		}
   405→	}
   406→
   407→	return nil
   408→}
   409→
   410→func (dv *RODataColumnsVerifier) SidecarDescendsFromFinalized() (err error) {
   411→	if ok, err := dv.results.cached(RequireSidecarDescendsFromFinalized); ok {
   412→		return err
   413→	}
   414→
   415→	defer dv.recordResult(RequireSidecarDescendsFromFinalized, &err)
   416→
   417→	for _, dataColumn := range dv.dataColumns {
   418→		// Extract the root of the parent block corresponding to the data column.
   419→		parentRoot := dataColumn.ParentRoot()
   420→
   421→		if !dv.fc.HasNode(parentRoot) {
   422→			return columnErrBuilder(errSidecarNotFinalizedDescendent)
   423→		}
   424→	}
   425→
   426→	return nil
   427→}
   428→
   429→func (dv *RODataColumnsVerifier) SidecarInclusionProven() (err error) {
   430→	if ok, err := dv.results.cached(RequireSidecarInclusionProven); ok {
   431→		return err
   432→	}
   433→
   434→	defer dv.recordResult(RequireSidecarInclusionProven, &err)
   435→
   436→	startTime := time.Now()
   437→
   438→	for _, dataColumn := range dv.dataColumns {
   439→		k, keyErr := inclusionProofKey(dataColumn)
   440→		if keyErr == nil {
   441→			if _, ok := dv.ic.Get(k); ok {
   442→				continue
   443→			}
   444→		} else {
   445→			log.WithError(keyErr).Error("Failed to get inclusion proof key")
   446→		}
   447→
   448→		if err = peerdas.VerifyDataColumnSidecarInclusionProof(dataColumn); err != nil {
   449→			return columnErrBuilder(ErrSidecarInclusionProofInvalid)
   450→		}
   451→
   452→		if keyErr == nil {
   453→			dv.ic.Add(k, struct{}{})
   454→		}
   455→	}
   456→
   457→	dataColumnSidecarInclusionProofVerificationHistogram.Observe(float64(time.Since(startTime).Milliseconds()))
   458→
   459→	return nil
   460→}
   461→
   462→func (dv *RODataColumnsVerifier) SidecarKzgProofVerified() (err error) {
   463→	if ok, err := dv.results.cached(RequireSidecarKzgProofVerified); ok {
   464→		return err
   465→	}
   466→
   467→	defer dv.recordResult(RequireSidecarKzgProofVerified, &err)
   468→
   469→	startTime := time.Now()
   470→
   471→	err = dv.verifyDataColumnsCommitment(dv.dataColumns)
   472→	if err != nil {
   473→		return columnErrBuilder(errors.Wrap(err, "verify data column commitment"))
   474→	}
   475→
   476→	DataColumnBatchKZGVerificationHistogram.WithLabelValues("direct").Observe(float64(time.Since(startTime).Milliseconds()))
   477→	return nil
   478→}
   479→
   480→func (dv *RODataColumnsVerifier) SidecarProposerExpected(ctx context.Context) (err error) {
   481→	if ok, err := dv.results.cached(RequireSidecarProposerExpected); ok {
   482→		return err
   483→	}
   484→
   485→	defer dv.recordResult(RequireSidecarProposerExpected, &err)
   486→
   487→	for _, dataColumn := range dv.dataColumns {
   488→		dataColumnSlot := dataColumn.Slot()
   489→
   490→		// Get the verifying state, it is guaranteed to have the correct proposer in the lookahead.
   491→		verifyingState, err := dv.getVerifyingState(ctx, dataColumn)
   492→		if err != nil {
   493→			return columnErrBuilder(errors.Wrap(err, "verifying state"))
   494→		}
   495→
   496→		// Use proposer lookahead directly
   497→		idx, err := helpers.BeaconProposerIndexAtSlot(ctx, verifyingState, dataColumnSlot)
   498→		if err != nil {
   499→			return columnErrBuilder(errors.Wrap(err, "proposer from lookahead"))
   500→		}
   501→
   502→		if idx != dataColumn.ProposerIndex() {
   503→			return columnErrBuilder(errSidecarUnexpectedProposer)
   504→		}
   505→	}
   506→
   507→	return nil
   508→}
   509→
   510→func columnToSignatureData(d blocks.RODataColumn) signatureData {
   511→	return signatureData{
   512→		Root:      d.BlockRoot(),
   513→		Parent:    d.ParentRoot(),
   514→		Signature: bytesutil.ToBytes96(d.SignedBlockHeader.Signature),
   515→		Proposer:  d.ProposerIndex(),
   516→		Slot:      d.Slot(),
   517→	}
   518→}
   519→
   520→func columnErrBuilder(baseErr error) error {
   521→	return errors.Wrap(baseErr, errColumnsInvalid.Error())
   522→}
   523→
   524→// incluseionProofKey computes a unique key based on the KZG commitments,
   525→// the KZG commitments inclusion proof, and the signed block header root.
   526→func inclusionProofKey(c blocks.RODataColumn) ([32]byte, error) {
   527→	const (
   528→		commsIncProofLen       = 4
   529→		commsIncProofByteCount = commsIncProofLen * 32
   530→	)
   531→
   532→	if len(c.KzgCommitmentsInclusionProof) != commsIncProofLen {
   533→		// This should be already enforced by ssz unmarshaling; still check so we don't panic on array bounds.
   534→		return [32]byte{}, columnErrBuilder(ErrSidecarInclusionProofInvalid)
   535→	}
   536→
   537→	commsByteCount := len(c.KzgCommitments) * fieldparams.KzgCommitmentSize
   538→	unhashedKey := make([]byte, 0, commsIncProofByteCount+fieldparams.RootLength+commsByteCount)
   539→
   540→	// Include the commitments inclusion proof in the key.
   541→	for _, proof := range c.KzgCommitmentsInclusionProof {
   542→		unhashedKey = append(unhashedKey, proof...)
   543→	}
   544→
   545→	// Include the block root in the key.
   546→	root, err := c.SignedBlockHeader.HashTreeRoot()
   547→	if err != nil {
   548→		return [32]byte{}, columnErrBuilder(errors.Wrap(err, "hash tree root"))
   549→	}
   550→
   551→	unhashedKey = append(unhashedKey, root[:]...)
   552→
   553→	// Include the commitments in the key.
   554→	for _, commitment := range c.KzgCommitments {
   555→		unhashedKey = append(unhashedKey, commitment...)
   556→	}
   557→
   558→	return sha256.Sum256(unhashedKey), nil
   559→}
